export async function generateStaticParams() {
  return DATA.map((d) => ({ slug: d.slug }));
}

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<import("next").Metadata> {
  const { slug } = await params;
  const d = DATA.find((x) => x.slug === slug) ?? DATA[0];
  return {
    title: d.title,
    description: d.desc,
    keywords: ["태몽해몽", "육아사주", "아기사주", "점운육아일기", "임신운세", "아기이름사주"],
    openGraph: { title: d.title, description: d.desc, url: `https://jeomun.com/momcare/guide/${d.slug}` },
  };
}

